pub(crate) fn embedded_outfit_layer(value:&serde_json::Value,key:&str,size:(u32,u32))->Result<Option<Vec<u8>>,String>{
 let Some(v)=value.get(key) else{return Ok(None)};let a=v.as_array().ok_or("Invalid outfit layer")?;if a.len()>16_000_000{return Err("Outfit layer too large".into())}let bytes:Vec<u8>=a.iter().map(|v|v.as_u64().filter(|v|*v<=255).map(|v|v as u8).ok_or("Invalid layer byte".to_string())).collect::<Result<_,_>>()?;if png_dimensions(&bytes)?!=size{return Err("Outfit layer dimensions do not match body".into())}Ok(Some(bytes))
}
use std::{fs,io::Write,path::{Path,PathBuf}};
pub(crate) fn png_dimensions(bytes:&[u8])->Result<(u32,u32),String>{
 if bytes.len()<33||bytes.len()>16_000_000||!bytes.starts_with(b"\x89PNG\r\n\x1a\n")||&bytes[12..16]!=b"IHDR"||bytes[24]!=8||bytes[25]!=6{return Err("Use an RGBA PNG under 16 MB.".into());}
 let w=u32::from_be_bytes(bytes[16..20].try_into().unwrap());let h=u32::from_be_bytes(bytes[20..24].try_into().unwrap());if w<128||h<128||w>2048||h>2048{return Err("Outfit canvas must be 128–2048 pixels per side.".into());}Ok((w,h))
}
pub(crate) fn validate_output(bytes:&[u8],metadata:&str)->Result<(),String>{
 let (w,h)=png_dimensions(bytes)?;if metadata.len()>16_000_000{return Err("Outfit selection is too large.".into());}let data:serde_json::Value=serde_json::from_str(metadata).map_err(|_|"Invalid outfit selection")?;if data["width"].as_u64()!=Some(w as u64)||data["height"].as_u64()!=Some(h as u64)||data["prototype"]!=true{return Err("Outfit dimensions do not match selection details.".into());}
 Ok(())
}
fn write(dir:&Path,bytes:&[u8],metadata:&str)->Result<PathBuf,String>{write_named(dir,bytes,metadata,"prototype")}
fn write_named(dir:&Path,bytes:&[u8],metadata:&str,prefix:&str)->Result<PathBuf,String>{
 validate_output(bytes,metadata)?;let value:serde_json::Value=serde_json::from_str(metadata).map_err(|e|e.to_string())?;let back=embedded_outfit_layer(&value,"outfitBackBytes",png_dimensions(bytes)?)?;if let Some(project)=value.get("editorProject"){crate::generated_outfits::validate_project(project)?;}
 fs::create_dir_all(dir).map_err(|e|e.to_string())?;let target=dir.join(format!("{prefix}-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_err(|e|e.to_string())?.as_nanos()));fs::create_dir(&target).map_err(|e|e.to_string())?;
 let result=(||{let mut file=fs::OpenOptions::new().write(true).create_new(true).open(target.join("outfit.png")).map_err(|e|e.to_string())?;file.write_all(bytes).map_err(|e|e.to_string())?;file.sync_all().map_err(|e|e.to_string())?;if let Some(back)=&back{fs::write(target.join("outfit_back.png"),back).map_err(|e|e.to_string())?;}if let Some(project)=value.get("editorProject"){fs::write(target.join("project.json"),serde_json::to_vec(project).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;}fs::write(target.join("selection.json"),metadata).map_err(|e|e.to_string())?;Ok(target.clone())})();
 if result.is_err(){let _=fs::remove_file(target.join("outfit_back.png"));let _=fs::remove_file(target.join("project.json"));let _=fs::remove_file(target.join("outfit.png"));let _=fs::remove_file(target.join("selection.json"));let _=fs::remove_dir(&target);}result
}
#[tauri::command]pub fn outfit_prototype_export(bytes:Vec<u8>,metadata:String)->Result<String,String>{write(Path::new(r"C:\AI\ManaAI-CV-2\exports\outfits"),&bytes,&metadata).map(|p|p.to_string_lossy().to_string())}
