#[derive(serde::Deserialize)]pub struct AtelierLayer{pub slot:String,pub bytes:Vec<u8>}
fn install_item(root:&Path,category:&str,depth:&str,layers:&[AtelierLayer],metadata:&str)->Result<PathBuf,String>{
 if !matches!(category,"hair"|"accessory")||layers.is_empty()||layers.len()>2{return Err("Choose hair or accessory layers.".into());}
 let mut seen=std::collections::HashSet::new();let mut dimensions=None;
 for layer in layers{validate_output(&layer.bytes,metadata)?;let d=png_dimensions(&layer.bytes)?;if dimensions.is_some()&&dimensions!=Some(d){return Err("Layer dimensions must match.".into());}dimensions=Some(d);if !seen.insert(layer.slot.as_str())||!(if category=="hair"{matches!(layer.slot.as_str(),"front"|"back")}else{layer.slot=="front"}){return Err("Invalid item layer.".into());}}
 if !seen.contains("front")||category=="accessory"&&(!matches!(depth,"back"|"behind-body"|"behind-front-hair"|"top")||layers.len()!=1){return Err("Missing front layer or invalid accessory depth.".into());}
 let value:serde_json::Value=serde_json::from_str(metadata).map_err(|_|"Invalid item metadata")?;let label=value["name"].as_str().unwrap_or("item");let slug:String=label.chars().take(50).map(|c|if c.is_ascii_alphanumeric(){c.to_ascii_lowercase()}else{'_'}).collect();let id=format!("atelier_{}-{}",slug.trim_matches('_'),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_err(|e|e.to_string())?.as_nanos());
 fs::create_dir_all(root).map_err(|e|e.to_string())?;let base=root.canonicalize().map_err(|e|e.to_string())?;let folder=if category=="hair"{base.join("hairstyles")}else{base.join("accessories").join(depth)};fs::create_dir_all(&folder).map_err(|e|e.to_string())?;if !folder.canonicalize().map_err(|e|e.to_string())?.starts_with(&base){return Err("Item folder escapes wardrobe.".into());}
 if category=="hair"{let target=folder.join(id);fs::create_dir(&target).map_err(|e|e.to_string())?;let result=(||{for layer in layers{let mut file=fs::OpenOptions::new().write(true).create_new(true).open(target.join(format!("hair_{}.png",layer.slot))).map_err(|e|e.to_string())?;file.write_all(&layer.bytes).map_err(|e|e.to_string())?;file.sync_all().map_err(|e|e.to_string())?;}fs::write(target.join("selection.json"),metadata).map_err(|e|e.to_string())?;Ok(target.clone())})();if result.is_err(){for file in ["hair_front.png","hair_back.png","selection.json"]{let _=fs::remove_file(target.join(file));}let _=fs::remove_dir(&target);}result}
 else{let target=folder.join(format!("{id}.png"));let sidecar=folder.join(format!("{id}.selection.json"));let result=(||{let mut file=fs::OpenOptions::new().write(true).create_new(true).open(&target).map_err(|e|e.to_string())?;file.write_all(&layers[0].bytes).map_err(|e|e.to_string())?;file.sync_all().map_err(|e|e.to_string())?;fs::write(&sidecar,metadata).map_err(|e|e.to_string())?;Ok(target.clone())})();if result.is_err(){let _=fs::remove_file(&target);let _=fs::remove_file(&sidecar);}result}
}
pub fn imported_item(rel:&str)->bool{let p:Vec<_>=rel.split('/').collect();match p.as_slice(){["outfits",id,file]=>id.starts_with("atelier_")&&matches!(*file,"outfit.png"|"outfit_back.png"),["hairstyles",id,file]=>id.starts_with("atelier_")&&matches!(*file,"hair_front.png"|"hair_back.png"),["accessories",depth,file]=>matches!(*depth,"back"|"behind-body"|"behind-front-hair"|"top")&&file.starts_with("atelier_")&&file.ends_with(".png"),_=>false}}
#[tauri::command]pub fn atelier_item_save(app:tauri::AppHandle,category:String,depth:String,layers:Vec<AtelierLayer>,metadata:String)->Result<String,String>{install_item(&library_root(&app)?,&category,&depth,&layers,&metadata).map(|p|p.to_string_lossy().to_string())}

#[tauri::command]pub fn atelier_item_export(category:String,depth:String,layers:Vec<AtelierLayer>,metadata:String)->Result<String,String>{install_item(Path::new(r"C:\AI\ManaAI-CV-2\exports\atelier"),&category,&depth,&layers,&metadata).map(|p|p.to_string_lossy().to_string())}

#[cfg(test)]mod atelier_item_tests{use super::*;#[test]fn installs_hair_and_accessories_at_validated_slots(){let root=std::env::temp_dir().join(format!("mana-atelier-items-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));let bytes=include_bytes!("../../tests/fixtures/outfit-alpha.png").to_vec();let metadata=r#"{"width":128,"height":128,"prototype":true,"name":"Hair test"}"#;let layers=vec![AtelierLayer{slot:"front".into(),bytes:bytes.clone()},AtelierLayer{slot:"back".into(),bytes:bytes.clone()}];let hair=install_item(&root,"hair","top",&layers,metadata).unwrap();assert!(hair.join("hair_front.png").is_file());assert!(hair.join("hair_back.png").is_file());for depth in ["back","behind-body","behind-front-hair","top"]{let path=install_item(&root,"accessory",depth,&layers[..1],metadata).unwrap();let rel=path.strip_prefix(root.canonicalize().unwrap()).unwrap().to_string_lossy().replace('\\',"/");assert!(imported_item(&rel));assert_eq!(fs::read(&path).unwrap(),bytes);}let paths=crate::avatar_files::scan(&root).unwrap();assert_eq!(paths.len(),6);assert!(paths.iter().all(|p|imported_item(p)));for rel in &paths{assert_eq!(crate::avatar_files::read(&root,rel).unwrap(),bytes);}assert!(install_item(&root,"accessory","../escape",&layers[..1],metadata).is_err());assert!(install_item(&root,"hair","top",&layers[1..],metadata).is_err());assert!(!imported_item("hairstyles/atelier_test/../../bad.png"));assert_eq!(root.canonicalize().unwrap().parent().unwrap(),std::env::temp_dir().canonicalize().unwrap());assert!(root.file_name().unwrap().to_string_lossy().starts_with("mana-atelier-items-"));fs::remove_dir_all(root).unwrap();}}

fn write_project_backup(dir:&Path,data:&str)->Result<PathBuf,String>{
 if data.len()>48_000_000{return Err("Editable project exceeds 48 MB".into())}let v:serde_json::Value=serde_json::from_str(data).map_err(|e|e.to_string())?;
 if v["format"]!="mana-atelier-project"||v["version"]!=1||!matches!(v["category"].as_str(),Some("outfit"|"hair"|"accessory")){return Err("Invalid editable project backup".into())}crate::generated_outfits::validate_project(&v["project"])?;
 fs::create_dir_all(dir).map_err(|e|e.to_string())?;let path=dir.join(format!("project-{}.mana-project.json",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_err(|e|e.to_string())?.as_nanos()));let mut file=fs::OpenOptions::new().write(true).create_new(true).open(&path).map_err(|e|e.to_string())?;file.write_all(data.as_bytes()).map_err(|e|e.to_string())?;file.sync_all().map_err(|e|e.to_string())?;Ok(path)
}
#[tauri::command]pub fn atelier_project_export(data:String)->Result<String,String>{write_project_backup(Path::new(r"C:\AI\ManaAI-CV-2\exports\atelier-projects"),&data).map(|p|p.to_string_lossy().to_string())}

#[cfg(test)]mod project_backup_tests{use super::*;#[test]fn backups_export_to_separate_files_and_reject_invalid_payloads(){let root=std::env::temp_dir().join(format!("mana-backup-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));let data=serde_json::json!({"format":"mana-atelier-project","version":1,"category":"outfit","project":{"sourceDataUrl":"data:image/png;base64,AA==","sourceSize":{"width":128,"height":128},"parts":[{"id":"dress"}],"history":{"past":[]}}}).to_string();let a=write_project_backup(&root,&data).unwrap();let b=write_project_backup(&root,&data).unwrap();assert_ne!(a,b);assert_eq!(fs::read_to_string(&a).unwrap(),data);assert!(write_project_backup(&root,"{}").is_err());assert_eq!(fs::read_dir(&root).unwrap().count(),2);fs::remove_dir_all(root).unwrap();}}

#[tauri::command]pub fn outfit_wardrobe_project(app:tauri::AppHandle,id:String)->Result<Option<serde_json::Value>,String>{
 if !id.starts_with("atelier_")||!id.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'_'||b==b'-'){return Err("Invalid outfit ID".into())}let root=library_root(&app)?.join("outfits").canonicalize().map_err(|e|e.to_string())?;let path=root.join(id).join("project.json");if !path.exists(){return Ok(None)}let path=path.canonicalize().map_err(|e|e.to_string())?;if !path.starts_with(root)||fs::metadata(&path).map_err(|e|e.to_string())?.len()>48_000_000{return Err("Invalid outfit project".into())}let project=serde_json::from_slice(&fs::read(path).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;crate::generated_outfits::validate_project(&project)?;Ok(Some(project))
}

